class TestSchedulerPriority:
    def test_high_priority_task_executed_first(self, scheduler):
        s, _ = scheduler
        low_priority_id = s.submit_task(func_name="process_data", args=[1], priority=1)
        high_priority_id = s.submit_task(func_name="process_data", args=[2], priority=10)
        next_task = s.get_next_task()
        assert next_task == high_priority_id

    def test_equal_priority_tasks_fifo_order(self, scheduler):
        s, _ = scheduler
        first_id = s.submit_task(func_name="process_data", args=[1], priority=5)
        second_id = s.submit_task(func_name="process_data", args=[2], priority=5)
        next_task = s.get_next_task()
        assert next_task == first_id

